        if (user == null) {
            throw new BizException(ResultCodeEnum.USER_MOBILE_NOT_REGISTERED);
        }

        // 3. 根据登录类型做身份校验
        Integer type = dto.getType();
        if (LoginTypeEnum.PASSWORD.getCode().equals(type)) {
            checkPassword(dto.getPassword(), user.getPassword());
        } else if (LoginTypeEnum.VERIFY_CODE.getCode().equals(type)) {
            checkVerifyCode(dto.getVerifyCode());
        } else {
            throw new BizException(ResultCodeEnum.PARAM_NOT_VALID);
        }

        // 4. 校验账号状态（放在身份校验之后，避免向未验证身份的人泄露账号状态）
        if (UserStatusEnum.DISABLED.getCode().equals(user.getStatus())) {
            throw new BizException(ResultCodeEnum.USER_STATUS_DISABLED);
        }

        // 5. Sa-Token 登录
        StpUtil.login(user.getId());

        // 6. 获取 Token
        String token = StpUtil.getTokenValue();

        // 7. 组装响应
        LoginUserRspVO.UserInfo userInfo = new LoginUserRspVO.UserInfo();
        userInfo.setId(user.getId());
        userInfo.setNickname(user.getNickname());
        userInfo.setAvatar(user.getAvatar());        // ← 注意是 user 不是 userInfo

        LoginUserRspVO vo = new LoginUserRspVO();
        vo.setToken(token);
        vo.setUserInfo(userInfo);

        log.info("用户登录成功, userId={}, mobile={}", user.getId(), user.getMobile());
        return vo;
    }
```

