package com.practice.flashsale.common.utils;

import com.practice.flashsale.common.enums.ResultCodeEnum;
import com.practice.flashsale.common.exception.BizException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

/**
 * 登录相关校验器
 * <p>
 * 注意：这里不是工具类，而是 Spring Bean（需要注入 BCryptPasswordEncoder）。
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class LoginValidator {

    private final BCryptPasswordEncoder passwordEncoder;

    /**
     * 校验密码
     *
     * @param rawPassword     用户输入的明文密码
     * @param encodedPassword 数据库中存储的密文密码
     */
    public void checkPassword(String rawPassword, String encodedPassword) {
        // 1. 判空：passwordEncoder.matches(null, ...) 会抛 IllegalArgumentException
        if (!StringUtils.hasText(rawPassword)) {
            throw new BizException(ResultCodeEnum.USER_PASSWORD_ERROR);
        }

        // 2. BCrypt 校验必须用 matches()，不能用 equals()（每次加密结果都不同）
        if (!passwordEncoder.matches(rawPassword, encodedPassword)) {
            // TODO 3.6 节：在这里记录密码错误次数，超限锁定账号
            //      届时签名改为 checkPassword(String mobile, String rawPassword, String encodedPassword)
            throw new BizException(ResultCodeEnum.USER_PASSWORD_ERROR);
        }
    }

    /**
     * 校验短信验证码
     * <p>
     * 验证码发送接口在 3.3 节开发，校验逻辑在 3.4 节接入。
     * 当前【默认拒绝】（fail-closed）：宁可暂时不可用，也不能放过未校验的请求。
     *
     * @param verifyCode 用户输入的验证码
     */
    public void checkVerifyCode(String verifyCode) {
        if (!StringUtils.hasText(verifyCode)) {
            throw new BizException(ResultCodeEnum.USER_VERIFY_CODE_ERROR);
        }

        // TODO 3.4 节注入 CaptchaService 后替换成：
        // if (!captchaService.verify(mobile, verifyCode)) {
        //     throw new BizException(ResultCodeEnum.USER_VERIFY_CODE_ERROR);
        // }
        // return;

        log.warn("验证码登录暂未开放, verifyCode={}", verifyCode);
        throw new BizException(ResultCodeEnum.USER_VERIFY_CODE_ERROR);
    }
}
```

