```java
package com.practice.flashsale.user.service.impl;

import com.practice.flashsale.common.constant.RedisKeyConstant;
import com.practice.flashsale.common.enums.ResultCodeEnum;
import com.practice.flashsale.common.exception.BizException;
import com.practice.flashsale.user.component.SmsService;
import com.practice.flashsale.user.enums.VerifyCodeTypeEnum;
import com.practice.flashsale.user.model.dto.SendVerifyCodeReqDTO;
import com.practice.flashsale.user.service.VerifyCodeService;
import jakarta.annotation.Resource;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import java.util.concurrent.Executor;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

@Slf4j
@Service
@RequiredArgsConstructor
public class VerifyCodeServiceImpl implements VerifyCodeService {

    /** 验证码有效期：5 分钟 */
    private static final long CODE_EXPIRE_MINUTES = 5;

    /** 同一手机号发送间隔：60 秒 */
    private static final long SEND_INTERVAL_SECONDS = 60;

    /** 验证码位数 */
    private static final int CODE_LENGTH = 6;

    private final StringRedisTemplate stringRedisTemplate;
    private final SmsService smsService;

    /**
     * 容器里有多个 Executor（Spring Boot 自带的 applicationTaskExecutor + 我们的 bizExecutor），
     * 必须用 @Resource(name=...) 显式指定，否则启动会报 expected single matching bean
     */
    @Resource(name = "bizExecutor")
    private Executor bizExecutor;

    @Override
    public void sendVerifyCode(SendVerifyCodeReqDTO dto) {
        String mobile = dto.getMobile();

        // ========== 1. 校验验证码类型 ==========
        VerifyCodeTypeEnum typeEnum = VerifyCodeTypeEnum.of(dto.getType());
        if (typeEnum == null) {
            throw new BizException(ResultCodeEnum.VERIFY_CODE_TYPE_ERROR);
        }

        // ========== 2. 频控：同一手机号 60 秒内只能发一次 ==========
        // setIfAbsent = Redis 的 SET key value NX EX seconds，原子操作
        String limitKey = String.format(RedisKeyConstant.USER_VERIFY_CODE_LIMIT, mobile);
        Boolean firstSend = stringRedisTemplate.opsForValue()
                .setIfAbsent(limitKey, "1", SEND_INTERVAL_SECONDS, TimeUnit.SECONDS);
        if (!Boolean.TRUE.equals(firstSend)) {
            throw new BizException(ResultCodeEnum.VERIFY_CODE_SEND_TOO_FREQUENT);
        }

        // ========== 3. 生成 6 位数字验证码 ==========
        String verifyCode = generateVerifyCode();

        // ========== 4. 先写 Redis（同步、可控），再异步发短信 ==========
        String codeKey = String.format(RedisKeyConstant.USER_VERIFY_CODE,
                typeEnum.getPurpose(), mobile);
        stringRedisTemplate.opsForValue()
                .set(codeKey, verifyCode, CODE_EXPIRE_MINUTES, TimeUnit.MINUTES);

        // ========== 5. 异步发送短信，避免第三方接口耗时拖慢本接口 ==========
        bizExecutor.execute(() -> {
            try {
                smsService.sendVerifyCode(mobile, verifyCode);
            } catch (Exception e) {
                // 注意：异步线程里的异常不会传播到主线程，必须自己捕获并记录，否则会被静默吞掉
                log.error("短信发送失败, mobile={}", mobile, e);
            }
        });

        log.info("验证码已下发, mobile={}, type={}", mobile, typeEnum.getDescription());
    }

    /**
     * 生成 6 位数字验证码（允许首位为 0，例如 012345）
     */
    private String generateVerifyCode() {
        StringBuilder sb = new StringBuilder(CODE_LENGTH);
        for (int i = 0; i < CODE_LENGTH; i++) {
            sb.append(ThreadLocalRandom.current().nextInt(10));
        }
        return sb.toString();
    }
}
```

