package com.practice.flashsale.user.service.impl;

import cn.dev33.satoken.stp.StpUtil;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import com.practice.flashsale.common.constant.RedisKeyConstant;
import com.practice.flashsale.common.entity.User;
import com.practice.flashsale.common.enums.ResultCodeEnum;
import com.practice.flashsale.common.exception.BizException;
import com.practice.flashsale.common.mapper.UserMapper;
import com.practice.flashsale.user.component.SmsService;
import com.practice.flashsale.user.enums.LoginTypeEnum;
import com.practice.flashsale.user.enums.UserStatusEnum;
import com.practice.flashsale.user.enums.VerifyCodeTypeEnum;
import com.practice.flashsale.user.model.dto.LoginUserReqDTO;
import com.practice.flashsale.user.model.dto.RegisterUserReqDTO;
import com.practice.flashsale.user.model.dto.SendVerifyCodeReqDTO;
import com.practice.flashsale.user.model.vo.LoginUserRspVO;
import com.practice.flashsale.user.service.UserService;
import jakarta.annotation.Resource;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

import java.time.LocalDateTime;
import java.util.concurrent.Executor;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

@Slf4j
@Service
@RequiredArgsConstructor
public class UserServiceImpl implements UserService {

    // ==================== 常量 ====================
    /** 验证码有效期：5 分钟 */
    private static final long CODE_EXPIRE_MINUTES = 5;
    /** 同一手机号发送间隔：60 秒 */
    private static final long SEND_INTERVAL_SECONDS = 60;
    /** 验证码位数 */
    private static final int CODE_LENGTH = 6;

    // ==================== 依赖 ====================
    private final UserMapper userMapper;
    private final BCryptPasswordEncoder passwordEncoder;
    private final SmsService smsService;
    private final StringRedisTemplate stringRedisTemplate;

    /**
     * 容器里有多个 Executor（Spring Boot 自带的 applicationTaskExecutor + 我们的 bizExecutor），
     * 必须用 @Resource(name = "...") 显式指定 Bean 名，否则启动会报 expected single matching bean
     */
    @Resource(name = "bizExecutor")
    private Executor bizExecutor;

    // ==================================================================
    //  注册
    // ==================================================================
    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long register(RegisterUserReqDTO dto) {

        // 1. 两次密码一致性校验
        if (!dto.getPassword().equals(dto.getConfirmPassword())) {
            throw new BizException(ResultCodeEnum.USER_CONFIRM_PASSWORD_ERROR);
        }

        // 2. 手机号唯一性预检（友好提示，并发下不可靠）
        Long count = userMapper.selectCount(
                Wrappers.<User>lambdaQuery().eq(User::getMobile, dto.getMobile()));
        if (count != null && count > 0) {
            throw new BizException(ResultCodeEnum.USER_MOBILE_EXISTS);
        }

        // 3. 组装实体，密码 BCrypt 加密
        User user = new User();
        user.setMobile(dto.getMobile());
        user.setPassword(passwordEncoder.encode(dto.getPassword()));
        user.setStatus(UserStatusEnum.ENABLED.getCode());
        user.setCreateTime(LocalDateTime.now());
        user.setUpdateTime(LocalDateTime.now());
        // user.setNickname(NicknameUtils.generate());   // 如果注册时也要生成昵称，打开这行

        // 4. 落库，唯一索引兜底
        try {
            userMapper.insert(user);
        } catch (DuplicateKeyException e) {
            log.warn("注册并发冲突, mobile={}", dto.getMobile());
            throw new BizException(ResultCodeEnum.USER_MOBILE_EXISTS);
        }

        log.info("用户注册成功, userId={}, mobile={}", user.getId(), dto.getMobile());
        return user.getId();
    }

    // ==================================================================
    //  登录
    // ==================================================================
    @Override
    public LoginUserRspVO loginUser(LoginUserReqDTO dto) {

        // 1. 根据手机号查询用户
        User user = userMapper.selectOne(
                Wrappers.<User>lambdaQuery().eq(User::getMobile, dto.getMobile()));
        if (user == null) {
            throw new BizException(ResultCodeEnum.USER_MOBILE_NOT_REGISTERED);
        }

        // 2. 按登录类型做身份校验
        Integer type = dto.getType();
        if (LoginTypeEnum.PASSWORD.getCode().equals(type)) {
            checkPassword(dto.getPassword(), user.getPassword());
        } else if (LoginTypeEnum.VERIFY_CODE.getCode().equals(type)) {
            checkVerifyCode(dto.getVerifyCode());
        } else {
            throw new BizException(ResultCodeEnum.PARAM_NOT_VALID);
        }

        // 3. 校验账号状态（放在身份校验之后）
        if (UserStatusEnum.DISABLED.getCode().equals(user.getStatus())) {
            throw new BizException(ResultCodeEnum.USER_STATUS_DISABLED);
        }

        // 4. Sa-Token 执行登录并获取 Token
        StpUtil.login(user.getId());
        String token = StpUtil.getTokenValue();

        // 5. 组装用户信息
        LoginUserRspVO.UserInfo userInfo = new LoginUserRspVO.UserInfo();
        userInfo.setId(user.getId());
        userInfo.setNickname(user.getNickname());
        userInfo.setAvatar(user.getAvatar());

        LoginUserRspVO vo = new LoginUserRspVO();
        vo.setToken(token);
        vo.setUserInfo(userInfo);

        log.info("用户登录成功, userId={}, mobile={}", user.getId(), user.getMobile());
        return vo;
    }

    // ==================================================================
    //  发送短信验证码
    // ==================================================================
    @Override
    public void sendVerifyCode(SendVerifyCodeReqDTO dto) {
        String mobile = dto.getMobile();

        // 1. 校验验证码类型
        VerifyCodeTypeEnum typeEnum = VerifyCodeTypeEnum.of(dto.getType());
        if (typeEnum == null) {
            throw new BizException(ResultCodeEnum.VERIFY_CODE_TYPE_ERROR);
        }

        // 2. 频控：同一手机号 60 秒内只能发一次
        //    setIfAbsent = Redis 的 SET key value NX EX seconds，是原子操作
        String limitKey = String.format(RedisKeyConstant.USER_VERIFY_CODE_LIMIT, mobile);
        Boolean firstSend = stringRedisTemplate.opsForValue()
                .setIfAbsent(limitKey, "1", SEND_INTERVAL_SECONDS, TimeUnit.SECONDS);
        if (!Boolean.TRUE.equals(firstSend)) {
            throw new BizException(ResultCodeEnum.VERIFY_CODE_SEND_TOO_FREQUENT);
        }

        // 3. 生成 6 位数字验证码
        String verifyCode = generateVerifyCode();

        // 4. 先写 Redis（同步、可控），再异步发短信
        String codeKey = String.format(RedisKeyConstant.USER_VERIFY_CODE,
                typeEnum.getPurpose(), mobile);
        stringRedisTemplate.opsForValue()
                .set(codeKey, verifyCode, CODE_EXPIRE_MINUTES, TimeUnit.MINUTES);

        // 5. 异步发送短信，避免第三方接口耗时拖慢本接口
        bizExecutor.execute(() -> {
            try {
                smsService.sendVerifyCode(mobile, verifyCode);
            } catch (Exception e) {
                // 异步线程里的异常不会传播到主线程，必须自己捕获，否则会被静默吞掉
                log.error("短信发送失败, mobile={}", mobile, e);
            }
        });

        log.info("验证码已下发, mobile={}, type={}", mobile, typeEnum.getDescription());
    }

    // ==================================================================
    //  私有方法
    // ==================================================================

    /**
     * 校验密码
     */
    private void checkPassword(String rawPassword, String encodedPassword) {
        // matches(null, ...) 会抛 IllegalArgumentException，必须先判空
        if (!StringUtils.hasText(rawPassword)) {
            throw new BizException(ResultCodeEnum.USER_PASSWORD_ERROR);
        }
        // BCrypt 必须用 matches()，不能用 equals()
        if (!passwordEncoder.matches(rawPassword, encodedPassword)) {
            // TODO 3.6 节：在这里记录密码错误次数，超限锁定账号
            throw new BizException(ResultCodeEnum.USER_PASSWORD_ERROR);
        }
    }

    /**
     * 校验短信验证码（3.4 节接入 Redis 校验）
     */
    private void checkVerifyCode(String verifyCode) {
        if (!StringUtils.hasText(verifyCode)) {
            throw new BizException(ResultCodeEnum.USER_VERIFY_CODE_ERROR);
        }
        // TODO 3.4 节替换成从 Redis 取值比对（届时签名改为 checkVerifyCode(String mobile, String verifyCode)）
        log.warn("验证码登录暂未开放, verifyCode={}", verifyCode);
        throw new BizException(ResultCodeEnum.USER_VERIFY_CODE_ERROR);
    }

    /**
     * 生成 6 位数字验证码（允许首位为 0，例如 012345）
     */
    private String generateVerifyCode() {
        StringBuilder sb = new StringBuilder(CODE_LENGTH);
        for (int i = 0; i < CODE_LENGTH; i++) {
            sb.append(ThreadLocalRandom.current().nextInt(10));
        }
        return sb.toString();
    }
}
