            return;
        }

        int failCount = Convert.toInt(failCountStr, 0);
        if (failCount >= LOGIN_FAIL_MAX_COUNT) {
            log.warn("账号已被临时锁定, mobile={}, failCount={}", mobile, failCount);
            throw new BizException(ResultCodeEnum.LOGIN_FAIL_TOO_MANY);
        }
    }

    /**
     * 累加登录失败次数
     */
    private void addLoginFailCount(String mobile) {
        String failCountKey = LOGIN_FAIL_COUNT_KEY_PREFIX + mobile;

        Long failCount = stringRedisTemplate.opsForValue().increment(failCountKey);
        if (failCount == null) {
            // fail-closed 不适用于这里：计数失败不应该阻断登录流程，但必须留痕
            log.error("登录失败次数累加失败, mobile={}", mobile);
            return;
        }

        if (failCount == 1L) {
            // 第一次失败，开启 30 分钟窗口
            stringRedisTemplate.expire(failCountKey, LOGIN_LOCK_MINUTES, TimeUnit.MINUTES);
        } else if (failCount >= LOGIN_FAIL_MAX_COUNT) {
            // 达到上限，从此刻起重新锁定 30 分钟
            // （否则窗口快结束时触发的锁定，可能只剩几秒就自动解锁了）
            stringRedisTemplate.expire(failCountKey, LOGIN_LOCK_MINUTES, TimeUnit.MINUTES);
            log.warn("账号达到失败上限，已锁定 {} 分钟, mobile={}", LOGIN_LOCK_MINUTES, mobile);
        }
    }

    /**
     * 登录成功后清空失败计数
     */
    private void clearLoginFailCount(String mobile) {
        stringRedisTemplate.delete(LOGIN_FAIL_COUNT_KEY_PREFIX + mobile);
    }
